import fs from 'fs';

const content = fs.readFileSync('src/components/landing/google-2026-landing.tsx', 'utf8');

// Check 1: processedHeroIcons useMemo exists
if (!content.includes('const processedHeroIcons = useMemo')) {
  console.error('FAIL: processedHeroIcons useMemo not found');
  process.exit(1);
}

// Check 2: processedHeroIcons has [heroIcons] dependency (not query/activeColors)
const processedMatch = content.match(/const processedHeroIcons = useMemo\(\s*\(\)\s*=>\s*\{[\s\S]*?\},\s*\[([^\]]+)\]\)/);
if (!processedMatch) {
  console.error('FAIL: Could not parse processedHeroIcons useMemo dependencies');
  process.exit(1);
}
const deps = processedMatch[1].trim();
if (deps !== 'heroIcons') {
  console.error('FAIL: processedHeroIcons should depend only on [heroIcons], got [' + deps + ']');
  process.exit(1);
}

// Check 3: processedHeroIcons contains the optimization patterns
if (!content.includes('.join(" ")')) {
  console.error('FAIL: processedHeroIcons should contain .join(" ") for string processing');
  process.exit(1);
}
if (!content.includes('.toLowerCase()') || !content.match(/processedHeroIcons[\s\S]*\.toLowerCase\(\)/)) {
  console.error('FAIL: processedHeroIcons should contain .toLowerCase()');
  process.exit(1);
}
if (!content.includes('colorBucket(i.hex)')) {
  console.error('FAIL: processedHeroIcons should call colorBucket(i.hex)');
  process.exit(1);
}

// Check 4: filtered useMemo uses processedHeroIcons (not recomputing string processing)
const filteredMatch = content.match(/const filtered = useMemo\(\s*\(\)\s*=>\s*\{[\s\S]*?\},\s*\[([^\]]+)\]\)/);
if (!filteredMatch) {
  console.error('FAIL: Could not parse filtered useMemo dependencies');
  process.exit(1);
}
const filteredDeps = filteredMatch[1].trim();
if (!filteredDeps.includes('processedHeroIcons')) {
  console.error('FAIL: filtered should depend on processedHeroIcons');
  process.exit(1);
}

// Check 5: filtered does NOT contain .join() or colorBucket calls (they should be in processedHeroIcons)
const filteredBody = content.match(/const filtered = useMemo\(\s*\(\)\s*=>\s*\{([\s\S]*?)\},\s*\[processedHeroIcons/);
if (!filteredBody) {
  console.error('FAIL: Could not extract filtered body');
  process.exit(1);
}
// Check that filtered doesn't have .join() or colorBucket calls (those should only be in processedHeroIcons)
const hasJoinInFiltered = /\.join\(/.test(filteredBody[1]);
const hasColorBucketInFiltered = /colorBucket\(/.test(filteredBody[1]);
if (hasJoinInFiltered || hasColorBucketInFiltered) {
  console.error('FAIL: filtered should not contain .join() or colorBucket calls - those belong in processedHeroIcons');
  process.exit(1);
}

console.log('PASS: All optimization checks passed');
console.log('- processedHeroIcons useMemo exists with [heroIcons] dependency');
console.log('- processedHeroIcons contains .join(" "), .toLowerCase(), and colorBucket(i.hex)');
console.log('- filtered depends on processedHeroIcons');
console.log('- filtered does not contain redundant .join() or colorBucket calls');
